[CmdletBinding()]
param([string]$RepoRoot='')

Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
if(!$RepoRoot){$RepoRoot=Split-Path -Parent $PSScriptRoot};$RepoRoot=(Resolve-Path $RepoRoot).Path
. (Join-Path $RepoRoot 'tests/fixture-test-common.ps1')
Import-Module (Join-Path $RepoRoot 'scripts/lib/Harness.TaskState.psm1') -Force
Import-Module (Join-Path $RepoRoot 'scripts/lib/Harness.Governance.psm1') -Force
Import-Module (Join-Path $RepoRoot 'scripts/lib/Harness.Evidence.psm1') -Force
Import-Module (Join-Path $RepoRoot 'scripts/lib/Harness.Approval.psm1') -Force
Import-Module (Join-Path $RepoRoot 'scripts/lib/Harness.AtomicWrite.psm1') -Force
$taskScript=Join-Path $RepoRoot 'scripts/task.ps1';$script:passes=[Collections.Generic.List[string]]::new();$script:failures=[Collections.Generic.List[string]]::new()
function Check($Condition,$Pass,$Fail){if($Condition){$script:passes.Add($Pass)}else{$script:failures.Add($Fail)}}
function Snapshot($Root){return @(Get-ChildItem $Root -Force -Recurse|%{if($_.PSIsContainer){'D|'+$_.FullName}else{'F|'+$_.FullName+'|'+(Get-FileHash $_.FullName).Hash}}|Sort-Object)}
function Same($Before,$After,$Pass,$Fail){Check (@(Compare-Object @($Before) @($After)).Count -eq 0) $Pass $Fail}
function Complete-Cli($Handle){if(-not$Handle.Process.WaitForExit(30000)){$Handle.Process.Kill($true);throw 'CLI timeout'};$result=[pscustomobject]@{ExitCode=$Handle.Process.ExitCode;StdOut=$Handle.StdOut.GetAwaiter().GetResult().Trim();StdErr=$Handle.StdErr.GetAwaiter().GetResult().Trim()};$Handle.Process.Dispose();return $result}
function Invoke-Cli($Workspace,[string[]]$Arguments,$Fault='',$FaultBeforeFirstClaim=''){$old=$env:HARNESS_PROTOCOL;$oldFault=$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_AFTER_STEP;$oldPreclaim=$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_BEFORE_FIRST_CLAIM;try{$env:HARNESS_PROTOCOL='v2';if($Fault){$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_AFTER_STEP=$Fault}else{Remove-Item Env:DEV_HARNESS_TEST_TASK_STATE_FAIL_AFTER_STEP -ErrorAction Ignore};if($FaultBeforeFirstClaim){$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_BEFORE_FIRST_CLAIM=$FaultBeforeFirstClaim}else{Remove-Item Env:DEV_HARNESS_TEST_TASK_STATE_FAIL_BEFORE_FIRST_CLAIM -ErrorAction Ignore};return Complete-Cli (Start-RepoProcess -UserProfile $env:USERPROFILE -ScriptPath $taskScript -Arguments ($Arguments+@('-RepoRoot',$RepoRoot,'-WorkspaceRoot',$Workspace)))}finally{if($null-eq$old){Remove-Item Env:HARNESS_PROTOCOL -ErrorAction Ignore}else{$env:HARNESS_PROTOCOL=$old};if($null-eq$oldFault){Remove-Item Env:DEV_HARNESS_TEST_TASK_STATE_FAIL_AFTER_STEP -ErrorAction Ignore}else{$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_AFTER_STEP=$oldFault};if($null-eq$oldPreclaim){Remove-Item Env:DEV_HARNESS_TEST_TASK_STATE_FAIL_BEFORE_FIRST_CLAIM -ErrorAction Ignore}else{$env:DEV_HARNESS_TEST_TASK_STATE_FAIL_BEFORE_FIRST_CLAIM=$oldPreclaim}}}
function Read-Output($Result){if($Result.StdOut){return $Result.StdOut|ConvertFrom-Json -Depth 50 -DateKind String};return $null}
function Write-JsonFile($Workspace,$Relative,$Value){$path=Join-Path $Workspace $Relative;[void][IO.Directory]::CreateDirectory((Split-Path -Parent $path));[IO.File]::WriteAllText($path,(($Value|ConvertTo-Json -Depth 40)+"`n"),[Text.UTF8Encoding]::new($false))}
function Write-Contract($Workspace,$TaskId){
    $body=[ordered]@{schema_version='requirement-contract/v1';task_id=$TaskId;goal="Govern $TaskId.";acceptance=@('Governance requirements pass.');in_scope=@('v2 governance');out_of_scope=@('v1 stages');product_constraints=@('No fabricated review.');product_decisions=@();unresolved_product_decisions=@();source_authority=@('current-user-message')}
    $contract=[ordered]@{};foreach($key in $body.Keys){$contract[$key]=$body[$key]};$contract.digest=Get-HarnessSha256Text -Content ($body|ConvertTo-Json -Depth 30 -Compress)
    $relative="contracts/$TaskId.json";Write-JsonFile $Workspace $relative $contract;return [pscustomobject]@{Path=$relative;Digest=$contract.digest}
}
function Start-Verifying($Workspace,$TaskId,$Contract,[string[]]$Capabilities=@(),$Profile='governed'){
    $args=@('create','-TaskId',$TaskId,'-Contract',$Contract.Path,'-Profile',$Profile,'-AsJson');if($Capabilities.Count){$args+=@('-Capabilities')+$Capabilities}
    $created=Invoke-Cli $Workspace $args;$running=Invoke-Cli $Workspace @('transition','-TaskId',$TaskId,'-ExpectedVersion','1','-To','running','-AsJson');$verifying=Invoke-Cli $Workspace @('transition','-TaskId',$TaskId,'-ExpectedVersion','2','-To','verifying','-AsJson')
    if($created.ExitCode-or$running.ExitCode-or$verifying.ExitCode){throw "failed to prepare governed task: $TaskId`n$($created.StdErr)`n$($running.StdErr)`n$($verifying.StdErr)"};return Read-Output $created
}
function New-TestProtectedOperation([int]$TaskVersion,$ContractDigest,$Environment='production',[string[]]$Targets=@('db/customer.sql'),[string[]]$Scopes=@('rule:production-database-destructive','environment:production','path:db/customer.sql','dry-run:true')){return New-HarnessProtectedOperation -TaskVersion $TaskVersion -ContractDigest $ContractDigest -Environment $Environment -ActionCategory protected-write -Targets $Targets -ApprovalType production -ApprovalScope $Scopes}
function New-PassEvidence($Workspace,$TaskId,$ContractDigest,[int]$TaskVersion=3,[switch]$WithActor,[switch]$WithDryRun){
    $recordRelative=".harness/evidence/$TaskId.txt";$recordPath=Join-Path $Workspace $recordRelative;[void][IO.Directory]::CreateDirectory((Split-Path -Parent $recordPath));[IO.File]::WriteAllText($recordPath,"pass`n",[Text.UTF8Encoding]::new($false));$recordDigest='sha256:'+((Get-FileHash $recordPath).Hash.ToLowerInvariant())
    $record=[ordered]@{type='command';command='pwsh -File tests/governed.ps1';cwd='.';exit_code=0;executed_at=[DateTimeOffset]::UtcNow.ToString('o');evidence_path=$recordRelative;digest=$recordDigest;covers=@('AC-1')};if($WithActor){$record.actor=[ordered]@{host='codex';model='gpt-5';actor_id='actor-implementer';context_id='context-implementer'}}
    $document=[ordered]@{schema_version='evidence/v1';task_id=$TaskId;task_version=$TaskVersion;contract_digest=$ContractDigest;revision=('dirty:'+'0'*64);records=@($record);coverage=[ordered]@{satisfied=@('AC-1');not_verified=@();blocked=@()};gaps=@();conclusion='pass'}
    if($WithDryRun){$operation=New-TestProtectedOperation $TaskVersion $ContractDigest;$record.operation_identity=[string]$operation.identity;$record.covers=@('AC-1',[string]$operation.identity);$document.protected_operation=$operation;$dryRunRelative=".harness/evidence/$TaskId-dry-run.txt";$dryRunPath=Join-Path $Workspace $dryRunRelative;[IO.File]::WriteAllText($dryRunPath,"dry-run pass`n",[Text.UTF8Encoding]::new($false));$document.dry_run=[ordered]@{type='command';command='pwsh -File tests/governed.ps1 -DryRun';cwd='.';exit_code=0;executed_at=[DateTimeOffset]::UtcNow.ToString('o');evidence_path=$dryRunRelative;digest=('sha256:'+((Get-FileHash $dryRunPath).Hash.ToLowerInvariant()));covers=@([string]$operation.identity);operation_identity=[string]$operation.identity;actor=[ordered]@{host='controlled-executor';model='inherit';actor_id='executor-fixture';context_id='execution-fixture'}}}
    $relative="evidence-inputs/$TaskId.json";Write-JsonFile $Workspace $relative $document;$document.revision=Get-HarnessEvidenceRevision -WorkspaceRoot $Workspace -ContractDigest $ContractDigest -Evidence $document -EvidenceInputPath $relative -EvidenceOutputPath "docs/tasks/$TaskId/evidence.json";Write-JsonFile $Workspace $relative $document
    return [pscustomobject]@{Path=$relative;Document=$document;RecordPath=$recordRelative;RecordDigest=$recordDigest}
}
function Save-EvidenceFixture($Workspace,$Fixture,$ContractDigest){Write-JsonFile $Workspace $Fixture.Path $Fixture.Document;$Fixture.Document.revision=Get-HarnessEvidenceRevision -WorkspaceRoot $Workspace -ContractDigest $ContractDigest -Evidence $Fixture.Document -EvidenceInputPath $Fixture.Path -EvidenceOutputPath "docs/tasks/$($Fixture.Document.task_id)/evidence.json";Write-JsonFile $Workspace $Fixture.Path $Fixture.Document;return Resolve-HarnessEvidence -RepoRoot $RepoRoot -WorkspaceRoot $Workspace -TaskId ([string]$Fixture.Document.task_id) -TaskVersion ([int]$Fixture.Document.task_version) -ContractDigest $ContractDigest -RequiredAcceptanceCount 1 -EvidencePath $Fixture.Path}
function Set-EvidenceOperation($Fixture,$Operation){$old=[string]$Fixture.Document.protected_operation.identity;$Fixture.Document.protected_operation=$Operation;$record=$Fixture.Document.records[0];$record.operation_identity=[string]$Operation.identity;$record.covers=@($record.covers|Where-Object{$_-cne$old});if(@($record.covers)-cnotcontains[string]$Operation.identity){$record.covers+=@([string]$Operation.identity)};$Fixture.Document.dry_run.operation_identity=[string]$Operation.identity;$Fixture.Document.dry_run.covers=@([string]$Operation.identity)}
function Complete-Plan($Workspace,$TaskId){$path=Join-Path $Workspace "docs/tasks/$TaskId/plan.md";$text=[IO.File]::ReadAllText($path,[Text.Encoding]::UTF8);$text=$text.Replace('<fill-goal>','Implement the confirmed Contract.').Replace('<fill-scope>','Only governed v2 artifacts.').Replace('<fill-implementation>','Apply the smallest policy-required change.').Replace('<fill-verification>','Run the declared Evidence commands.').Replace('<fill-rollback>','Revert the governed change.');[IO.File]::WriteAllText($path,$text,[Text.UTF8Encoding]::new($false))}
function Write-Audit($Workspace,$TaskId,$ContractDigest,$EvidenceDigest,$ReviewerContext='context-reviewer',$ReviewerActor='actor-implementer',$Level='isolated-context',$Participated='false',$Findings='- none',[int]$TaskVersion=3,$Overrides=$null){
    $record=[ordered]@{implementer_actor_id='actor-implementer';reviewer_actor_id=$ReviewerActor;reviewer_context_id=$ReviewerContext;reviewer_base_model='gpt-5';independence_level=$Level;evidence_digest=$EvidenceDigest}
    if($Overrides){foreach($key in $Overrides.Keys){$record[$key]=$Overrides[$key]}}
    $template=[IO.File]::ReadAllText((Join-Path $RepoRoot 'templates/v2/audit.md.template'),[Text.Encoding]::UTF8);$text=$template.Replace('{{TASK_ID}}',$TaskId).Replace('{{TASK_VERSION}}',[string]$TaskVersion).Replace('{{CONTRACT_DIGEST}}',$ContractDigest).Replace('{{VERDICT}}','pass').Replace('{{REVIEWER_PARTICIPATED}}',$Participated).Replace('{{AUDIT_RECORD_JSON}}',($record|ConvertTo-Json -Depth 10)).Replace('{{FINDINGS}}',$Findings).Replace('{{EVIDENCE}}','Read-only diff and command evidence review.')
    $path=Join-Path $Workspace "docs/tasks/$TaskId/audit.md";[void][IO.Directory]::CreateDirectory((Split-Path -Parent $path));[IO.File]::WriteAllText($path,$text,[Text.UTF8Encoding]::new($false))
}
function Write-Approval($Workspace,$TaskId,$TaskVersion,$ContractDigest,$ApprovalId){$operation=New-TestProtectedOperation $TaskVersion $ContractDigest;$approval=[ordered]@{schema_version='approval/v1';approval_id=$ApprovalId;task_id=$TaskId;task_version=$TaskVersion;contract_digest=$ContractDigest;protected_operation=$operation;approval_type='production';approved_scope=@($operation.approval_scope);approver='fixture-user';approved_at=[DateTimeOffset]::UtcNow.AddMinutes(-1).ToString('o');expires_at=$null;status='granted'};$relative="approval-inputs/$ApprovalId.json";Write-JsonFile $Workspace $relative $approval;return $relative}
function Set-JournalStepContent($Journal,$Id,$Content){$step=@($Journal.steps|Where-Object{[string]$_.id-ceq$Id})[0];if($null-eq$step){throw "journal step is missing: $Id"};$step.content_base64=[Convert]::ToBase64String([Text.UTF8Encoding]::new($false).GetBytes($Content));$step.after_digest=Get-HarnessSha256Text -Content $Content}
function ConvertTo-LegacyJournal($Journal){
    $steps=@($Journal.steps|ForEach-Object{[ordered]@{id=[string]$_.id;relative_path=[string]$_.relative_path;action=[string]$_.action;before_digest=$_.before_digest;after_digest=$_.after_digest;content_base64=$_.content_base64}})
    $completed=@($Journal.completed_steps);$status=[string]$Journal.status;$failedStep=[string]$Journal.failed_step;$errorText=[string]$Journal.error
    if([string]$Journal.operation-ceq'verify'-and$completed.Count-eq0){$evidenceStep=@($steps|Where-Object{[string]$_.id-ceq'evidence'})[0];$target=Join-Path $workspace ([string]$evidenceStep.relative_path);[void][IO.Directory]::CreateDirectory((Split-Path -Parent $target));[IO.File]::WriteAllBytes($target,[Convert]::FromBase64String([string]$evidenceStep.content_base64));$completed=@('evidence');$status='failed';$failedStep='task-state';$errorText='legacy fixture after Evidence publication'}
    return [ordered]@{transaction_id=[string]$Journal.transaction_id;operation=[string]$Journal.operation;task_id=[string]$Journal.task_id;expected_version=$Journal.expected_version;status=$status;completed_steps=$completed;failed_step=$failedStep;error=$errorText;replay_command=[string]$Journal.replay_command;created_at=[string]$Journal.created_at;steps=$steps}
}

