    $taskStatePath=Join-Path $RepoRoot 'scripts/lib/Harness.TaskState.psm1';$taskStateTokens=$null;$taskStateErrors=$null;$taskStateAst=[Management.Automation.Language.Parser]::ParseFile($taskStatePath,[ref]$taskStateTokens,[ref]$taskStateErrors);$functionNodes=@($taskStateAst.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]},$true));$sharedGateExact=$true;foreach($target in @('Set-HarnessTaskEvidence','Assert-TransactionReplayInputs','Assert-LegacyTransactionReplayInputs')){$functionNode=@($functionNodes|Where-Object{$_.Name-ceq$target});$gateCalls=$(if($functionNode.Count-eq1){@($functionNode[0].Body.FindAll({param($node)$node-is[Management.Automation.Language.CommandAst]-and$node.GetCommandName()-ceq'Assert-HarnessGovernanceReady'},$true)).Count}else{0});if($gateCalls-ne1){$sharedGateExact=$false}};Check ($taskStateErrors.Count-eq0-and$sharedGateExact) 'normal verify plus current and legacy replay each call the shared governance gate exactly once' 'verify and replay governance gates drifted'

    $contracts=@{};foreach($taskId in @('optional-task','plan-task','audit-task','audit-whitespace-task','critical-task','critical-negative-task','critical-replay-task','critical-missing-replay-task','critical-operation-replay-task')){$contracts[$taskId]=Write-Contract $workspace $taskId}
    $created=Start-Verifying $workspace 'optional-task' $contracts['optional-task'];Check ($created.plan_action-ceq'not-required'-and-not(Test-Path (Join-Path $workspace 'docs/tasks/optional-task/plan.md'))-and-not(Test-Path (Join-Path $workspace 'docs/tasks/optional-task/audit.md'))) 'false governance policies create no plan or audit' 'optional task created governed artifacts'
