        $auditRecord=[ordered]@{implementer_actor_id='actor-implementer';reviewer_actor_id='actor-reviewer';reviewer_context_id='context-reviewer';reviewer_base_model='gpt-5';independence_level='isolated-context';evidence_digest=$auditWhitespaceResolved.Digest};$auditRecord[$field]=" `t"
        $auditSchemaValid=Test-Json -Json ($auditRecord|ConvertTo-Json -Depth 20 -Compress) -SchemaFile (Join-Path $RepoRoot 'schemas/audit-record.schema.json') -ErrorAction SilentlyContinue -WarningAction SilentlyContinue;Check (-not$auditSchemaValid) "Audit schema rejects whitespace-only $field" "Audit schema accepted whitespace-only $field"
        Write-Audit $workspace 'audit-whitespace-task' $contracts['audit-whitespace-task'].Digest $auditWhitespaceResolved.Digest -ReviewerActor 'actor-reviewer' -TaskVersion 3 -Overrides @{$field=" `t"};$before=Snapshot $workspace
        $auditWhitespaceResult=Invoke-Cli $workspace @('verify','-TaskId','audit-whitespace-task','-ExpectedVersion','3','-Evidence',$auditWhitespaceEvidence.Path,'-AsJson');Check ($auditWhitespaceResult.ExitCode-eq2-and$auditWhitespaceResult.StdErr-match"$field must not be blank") "Audit runtime rejects whitespace-only $field" "Audit runtime accepted whitespace-only $field";Same $before (Snapshot $workspace) "whitespace Audit $field rejection is zero-write" "whitespace Audit $field rejection wrote state"
    }
}finally{if(Test-Path $temp){Remove-DirectoryWithRetry -Path $temp}}
$repoAfter=@(& git -C $RepoRoot status --porcelain --untracked-files=all);Check (@(Compare-Object $repoBefore $repoAfter).Count-eq 0) 'governance verifier performs no repository writes' 'governance verifier changed repository state'
foreach($item in $script:passes){"[PASS] $item"};foreach($item in $script:failures){"[FAIL] $item"}
if($script:failures.Count){"STATUS: FAIL ($($script:failures.Count) failed)";exit 1};"STATUS: PASS ($($script:passes.Count) checks)";exit 0
